    AutoScalingGroupRecommendation.add_member(:auto_scaling_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupArn, location_name: 'autoScalingGroupArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Auto Scaling group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupName, location_name: 'autoScalingGroupName', traits: {"smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:finding, Smithy::Schema::Shapes::ShapeRef.new(shape: Finding, location_name: 'finding', traits: {"smithy.api#documentation" => "<p>The finding classification of the Auto Scaling group.</p>\n         <p>Findings for Auto Scaling groups include:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>NotOptimized</code>\n                  </b>—An Auto Scaling group is considered not optimized when Compute Optimizer identifies a\n                    recommendation that can provide better performance for your workload.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>Optimized</code>\n                  </b>—An Auto Scaling\n                    group is considered optimized when Compute Optimizer determines that the group\n                    is correctly provisioned to run your workload based on the chosen instance type.\n                    For optimized resources, Compute Optimizer might recommend a new generation\n                    instance type.</p>\n            </li>\n         </ul>"}))
    AutoScalingGroupRecommendation.add_member(:utilization_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: UtilizationMetrics, location_name: 'utilizationMetrics', traits: {"smithy.api#documentation" => "<p>An array of objects that describe the utilization metrics of the Auto Scaling\n            group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:look_back_period_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: LookBackPeriodInDays, location_name: 'lookBackPeriodInDays', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of days for which utilization metrics were analyzed for the Auto Scaling group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:current_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupConfiguration, location_name: 'currentConfiguration', traits: {"smithy.api#documentation" => "<p>An array of objects that describe the current configuration of the Auto Scaling\n            group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:current_instance_gpu_info, Smithy::Schema::Shapes::ShapeRef.new(shape: GpuInfo, location_name: 'currentInstanceGpuInfo', traits: {"smithy.api#documentation" => "<p>\n            Describes the GPU accelerator settings for the current instance type of the Auto Scaling group.\n        </p>"}))
    AutoScalingGroupRecommendation.add_member(:recommendation_options, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupRecommendationOptions, location_name: 'recommendationOptions', traits: {"smithy.api#documentation" => "<p>An array of objects that describe the recommendation options for the Auto Scaling\n            group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:last_refresh_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: LastRefreshTimestamp, location_name: 'lastRefreshTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp of when the Auto Scaling group recommendation was last\n            generated.</p>"}))
    AutoScalingGroupRecommendation.add_member(:current_performance_risk, Smithy::Schema::Shapes::ShapeRef.new(shape: CurrentPerformanceRisk, location_name: 'currentPerformanceRisk', traits: {"smithy.api#documentation" => "<p>The risk of the current Auto Scaling group not meeting the performance needs of\n            its workloads. The higher the risk, the more likely the current Auto Scaling group\n            configuration has insufficient capacity and cannot meet workload requirements.</p>"}))
    AutoScalingGroupRecommendation.add_member(:effective_recommendation_preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: EffectiveRecommendationPreferences, location_name: 'effectiveRecommendationPreferences', traits: {"smithy.api#documentation" => "<p>An object that describes the effective recommendation preferences for the Auto Scaling group.</p>"}))
    AutoScalingGroupRecommendation.add_member(:inferred_workload_types, Smithy::Schema::Shapes::ShapeRef.new(shape: InferredWorkloadTypes, location_name: 'inferredWorkloadTypes', traits: {"smithy.api#documentation" => "<p>The applications that might be running on the instances in the Auto Scaling group\n            as inferred by Compute Optimizer.</p>\n         <p>Compute Optimizer can infer if one of the following applications might be running on\n            the instances:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AmazonEmr</code> - Infers that Amazon EMR might be running on\n                    the instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ApacheCassandra</code> - Infers that Apache Cassandra might be running\n                    on the instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ApacheHadoop</code> - Infers that Apache Hadoop might be running on the\n                    instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Memcached</code> - Infers that Memcached might be running on the\n                    instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NGINX</code> - Infers that NGINX might be running on the\n                    instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PostgreSql</code> - Infers that PostgreSQL might be running on the\n                    instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Redis</code> - Infers that Redis might be running on the\n                    instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Kafka</code> - Infers that Kafka might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SQLServer</code> - Infers that SQLServer might be running on the\n                    instance.</p>\n            </li>\n         </ul>"}))
    AutoScalingGroupRecommendation.type = Types::AutoScalingGroupRecommendation
    AutoScalingGroupRecommendationOption.add_member(:configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupConfiguration, location_name: 'configuration', traits: {"smithy.api#documentation" => "<p>An array of objects that describe an Auto Scaling group configuration.</p>"}))
    AutoScalingGroupRecommendationOption.add_member(:instance_gpu_info, Smithy::Schema::Shapes::ShapeRef.new(shape: GpuInfo, location_name: 'instanceGpuInfo', traits: {"smithy.api#documentation" => "<p>\n            Describes the GPU accelerator settings for the recommended instance type of the Auto Scaling group.\n        </p>"}))
    AutoScalingGroupRecommendationOption.add_member(:projected_utilization_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectedUtilizationMetrics, location_name: 'projectedUtilizationMetrics', traits: {"smithy.api#documentation" => "<p>An array of objects that describe the projected utilization metrics of the Auto Scaling group recommendation option.</p>\n         <note>\n            <p>The <code>Cpu</code> and <code>Memory</code> metrics are the only projected\n                utilization metrics returned. Additionally, the <code>Memory</code> metric is\n                returned only for resources that have the unified CloudWatch agent installed\n                on them. For more information, see <a href=\"https://docs.aws.amazon.com/compute-optimizer/latest/ug/metrics.html#cw-agent\">Enabling Memory\n                    Utilization with the CloudWatch Agent</a>.</p>\n         </note>"}))
    AutoScalingGroupRecommendationOption.add_member(:performance_risk, Smithy::Schema::Shapes::ShapeRef.new(shape: PerformanceRisk, location_name: 'performanceRisk', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The performance risk of the Auto Scaling group configuration\n            recommendation.</p>\n         <p>Performance risk indicates the likelihood of the recommended instance type not meeting\n            the resource needs of your workload. Compute Optimizer calculates an individual\n            performance risk score for each specification of the recommended instance, including\n            CPU, memory, EBS throughput, EBS IOPS, disk throughput, disk IOPS, network throughput,\n            and network PPS.\n            The performance\n            risk of the recommended instance is calculated as the maximum performance risk score\n            across the analyzed resource specifications.</p>\n         <p>The value ranges from <code>0</code> - <code>4</code>, with <code>0</code> meaning\n            that the recommended resource is predicted to always provide enough hardware capability.\n            The higher the performance risk is, the more likely you should validate whether the\n            recommendation will meet the performance requirements of your workload before migrating\n            your resource.</p>"}))
    AutoScalingGroupRecommendationOption.add_member(:rank, Smithy::Schema::Shapes::ShapeRef.new(shape: Rank, location_name: 'rank', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The rank of the Auto Scaling group recommendation option.</p>\n         <p>The top recommendation option is ranked as <code>1</code>.</p>"}))
    AutoScalingGroupRecommendationOption.add_member(:savings_opportunity, Smithy::Schema::Shapes::ShapeRef.new(shape: SavingsOpportunity, location_name: 'savingsOpportunity', traits: {"smithy.api#documentation" => "<p>An object that describes the savings opportunity for the Auto Scaling group\n            recommendation option. Savings opportunity includes the estimated monthly savings amount\n            and percentage.</p>"}))
    AutoScalingGroupRecommendationOption.add_member(:savings_opportunity_after_discounts, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupSavingsOpportunityAfterDiscounts, location_name: 'savingsOpportunityAfterDiscounts', traits: {"smithy.api#documentation" => "<p>\n            An object that describes the savings opportunity for the Auto Scaling group recommendation option that includes Savings Plans and Reserved Instances discounts. \n            Savings opportunity includes the estimated monthly savings and percentage.\n        </p>"}))
    AutoScalingGroupRecommendationOption.add_member(:migration_effort, Smithy::Schema::Shapes::ShapeRef.new(shape: MigrationEffort, location_name: 'migrationEffort', traits: {"smithy.api#documentation" => "<p>The level of effort required to migrate from the current instance type to the\n            recommended instance type.</p>\n         <p>For example, the migration effort is <code>Low</code> if Amazon EMR is the\n            inferred workload type and an Amazon Web Services Graviton instance type is recommended.\n            The migration effort is <code>Medium</code> if a workload type couldn't be inferred but\n            an Amazon Web Services Graviton instance type is recommended. The migration effort is\n                <code>VeryLow</code> if both the current and recommended instance types are of the\n            same CPU architecture.</p>"}))
