    EBSSavingsOpportunityAfterDiscounts.add_member(:savings_opportunity_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: SavingsOpportunityPercentage, location_name: 'savingsOpportunityPercentage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>\n            The estimated monthly savings possible as a percentage of monthly cost after applying the specific discounts. \n            This saving can be achieved by adopting Compute Optimizer’s Amazon EBS volume recommendations.\n        </p>"}))
    EBSSavingsOpportunityAfterDiscounts.add_member(:estimated_monthly_savings, Smithy::Schema::Shapes::ShapeRef.new(shape: EBSEstimatedMonthlySavings, location_name: 'estimatedMonthlySavings', traits: {"smithy.api#documentation" => "<p>\n            The estimated monthly savings possible as a percentage of monthly cost by adopting Compute Optimizer’s Amazon EBS volume \n            recommendations. This saving includes any applicable discounts.\n        </p>"}))
