    InferredWorkloadSaving.add_member(:inferred_workload_types, Smithy::Schema::Shapes::ShapeRef.new(shape: InferredWorkloadTypes, location_name: 'inferredWorkloadTypes', traits: {"smithy.api#documentation" => "<p>The applications that might be running on the instance as inferred by Compute Optimizer.</p>\n         <p>Compute Optimizer can infer if one of the following applications might be running on\n            the instance:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AmazonEmr</code> - Infers that Amazon EMR might be running on\n                    the instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ApacheCassandra</code> - Infers that Apache Cassandra might be running\n                    on the instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ApacheHadoop</code> - Infers that Apache Hadoop might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Memcached</code> - Infers that Memcached might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NGINX</code> - Infers that NGINX might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PostgreSql</code> - Infers that PostgreSQL might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Redis</code> - Infers that Redis might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Kafka</code> - Infers that Kafka might be running on the\n                    instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SQLServer</code> - Infers that SQLServer might be running on the\n                    instance.</p>\n            </li>\n         </ul>"}))
    InferredWorkloadSaving.add_member(:estimated_monthly_savings, Smithy::Schema::Shapes::ShapeRef.new(shape: EstimatedMonthlySavings, location_name: 'estimatedMonthlySavings', traits: {"smithy.api#documentation" => "<p>An object that describes the estimated monthly savings amount possible by adopting Compute Optimizer recommendations for a given\n            resource. This is based on the On-Demand instance pricing.</p>"}))
