    InferredWorkloadType.add_member(:apache_cassandra, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'APACHE_CASSANDRA', traits: {"smithy.api#enumValue" => "ApacheCassandra"}))
