    InferredWorkloadType.add_member(:postgre_sql, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'POSTGRE_SQL', traits: {"smithy.api#enumValue" => "PostgreSql"}))
    InferredWorkloadType.add_member(:redis, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'REDIS', traits: {"smithy.api#enumValue" => "Redis"}))
