    InstanceEstimatedMonthlySavings.add_member(:currency, Smithy::Schema::Shapes::ShapeRef.new(shape: Currency, location_name: 'currency', traits: {"smithy.api#documentation" => "<p>\n            The currency of the estimated monthly savings.\n        </p>"}))
