    InstanceSavingsOpportunityAfterDiscounts.add_member(:savings_opportunity_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: SavingsOpportunityPercentage, location_name: 'savingsOpportunityPercentage', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>\n            The estimated monthly savings possible as a percentage of monthly cost after applying the Savings Plans and Reserved Instances discounts. \n            This saving can be achieved by adopting Compute Optimizer’s EC2 instance recommendations.\n        </p>"}))
    InstanceSavingsOpportunityAfterDiscounts.add_member(:estimated_monthly_savings, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceEstimatedMonthlySavings, location_name: 'estimatedMonthlySavings', traits: {"smithy.api#documentation" => "<p>\n            An object that describes the estimated monthly savings possible by adopting Compute Optimizer’s Amazon EC2 instance recommendations. This is \n            based on pricing after applying the Savings Plans and Reserved Instances discounts.\n        </p>"}))
