    RecommendationPreferencesDetail.add_member(:external_metrics_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: ExternalMetricsPreference, location_name: 'externalMetricsPreference', traits: {"smithy.api#documentation" => "<p> An object that describes the external metrics recommendation preference. </p>\n         <p> If the preference is applied in the latest recommendation refresh, an object with a\n            valid <code>source</code> value appears in the response. If the preference isn't applied\n            to the recommendations already, then this object doesn't appear in the response. </p>"}))
