    VolumeRecommendation.add_member(:volume_recommendation_options, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeRecommendationOptions, location_name: 'volumeRecommendationOptions', traits: {"smithy.api#documentation" => "<p>An array of objects that describe the recommendation options for the volume.</p>"}))
    VolumeRecommendation.add_member(:last_refresh_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: LastRefreshTimestamp, location_name: 'lastRefreshTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp of when the volume recommendation was last generated.</p>"}))
    VolumeRecommendation.add_member(:current_performance_risk, Smithy::Schema::Shapes::ShapeRef.new(shape: CurrentPerformanceRisk, location_name: 'currentPerformanceRisk', traits: {"smithy.api#documentation" => "<p>The risk of the current EBS volume not meeting the performance needs of its workloads.\n            The higher the risk, the more likely the current EBS volume doesn't have sufficient\n            capacity.</p>"}))
