    VolumeRecommendationOption.add_member(:performance_risk, Smithy::Schema::Shapes::ShapeRef.new(shape: PerformanceRisk, location_name: 'performanceRisk', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The performance risk of the volume recommendation option.</p>\n         <p>Performance risk is the likelihood of the recommended volume type meeting the\n            performance requirement of your workload.</p>\n         <p>The value ranges from <code>0</code> - <code>4</code>, with <code>0</code> meaning\n            that the recommended resource is predicted to always provide enough hardware capability.\n            The higher the performance risk is, the more likely you should validate whether the\n            recommendation will meet the performance requirements of your workload before migrating\n            your resource.</p>"}))
    VolumeRecommendationOption.add_member(:rank, Smithy::Schema::Shapes::ShapeRef.new(shape: Rank, location_name: 'rank', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The rank of the volume recommendation option.</p>\n         <p>The top recommendation option is ranked as <code>1</code>.</p>"}))
